mapper.update:
update setmeal
set status=#{status},
    update_time=NOW(),
    update_user=${@com.dingdingcatering.context.BaseContext@getCurrentId()}
where id = #{id}

update setmeal
category_id=#{categoryId}, name=#{name}, description=#{description}, image=#{image}, price=#{price}, status=#{status}, update_time=#{updateTime},update_user=#{updateUser}
where id = #{id}

mapper.select:
select s.id,s.category_id,s.name,s.price,s.status,s.description,s.image,s.update_time,c.name as categoryName, sd.id as setmeal_dish_id, sd.setmeal_id, sd.dish_id, sd.name as dish_name, sd.price as dish_price, sd.copies, f.id as flavor_id, f.flavor_name, f.value_list from setmeal s left join category c on c.id = s.category_id left join setmeal_dish sd on sd.setmeal_id = s.id left join dish_flavor df on sd.dish_id = df.dish_id left join flavor f on df.flavor_id = f.id
and s.name like concat('%',#{name},'%') and s.status=#{status} and s.category_id =#{categoryId}
order by s.update_time desc, sd.id

select count(*)
from setmeal
where category_id = #{categoryId}

select dish_id
from setmeal_dish
where setmeal_id = #{id};

select s.name from setmeal s where s.id in

    #{id}

and status = ${@com.dingdingcatering.constant.StatusConstant@ENABLE}

update.foreach:
delete from dish_flavor where dish_id = #{item.dishId};
insert into dish_flavor (dish_id, flavor_id, flavor_name, value_list) values

    (#{item.dishId}, #{flavor.id}, #{flavor.flavorName}, #{flavor.valueList})

mapper.select:
select s.id, s.category_id, s.name, s.price, s.status, s.description, s.image, s.update_time, c.name as categoryName from setmeal s left join category c on c.id = s.category_id
and s.name like concat('%',#{name},'%') and s.status=#{status} and s.category_id =#{categoryId}
order by s.update_time desc

select sd.setmeal_id, sd.id, sd.dish_id, sd.name as dish_name, sd.price as dish_price, sd.copies, f.id as flavor_id, f.flavor_name, f.value_list from setmeal_dish sd left join dish_flavor df on sd.dish_id = df.dish_id left join flavor f on df.flavor_id = f.id where sd.setmeal_id in
#{id}
order by sd.setmeal_id, sd.id
